# 判断质数

```
bool IsPrime(int n)
{
    if(n <= 1)return false;
    for (int i = 2; i < n; i++)if ((n % i) == 0)return false;
    return true;
}
```

# 回文数转化

```
int huiwen(int num)
{	
	int g = 0;
	while(num>0){
		g=g*10+num%10;
		num/=10;
	}
	return g;
}
```

# 插入数组元素，并按正序排序

```
#include <iostream>
#include<algorithm>
using namespace std;
int main(){
	int n,m,temp;
	cin >> n >>m;
	int a[1000];
	for(int i = 0;i<m;i++){
		cin >> a[i];
	}
	a[m++]=n;
	sort(a,a+m,less<int>());
	for(int i = 0;i<m;i++){
		cout << a[i]<<" ";
	}
	return 0;
}
```

# 删除数组元素

```
#include <iostream>
using namespace std;
int main(){
	int n,x,temp;
	cin >> n;
	int a[n];
	for(int i = 0 ; i<n;i++){
		cin >> a[i];
	}
	cin >> x;
	a[x-1]=0;
	for(int i = 0;i<n;i++){
		if(a[i] != 0){
			cout << a[i]<<" ";
		}
	}
	return 0;
}
```

# 求一个数各个数位之和

```
int digitSum(int num) {
    int sum = 0;
    while (num > 0) {
        sum += num % 10;
        num /= 10;
    }
    return sum;
}
```

# 十进制数转二进制数

```
int to2(int n){
    long long s=0,a=1;
    while(n){
   	if(n%2==1)s+=a;
        n/=2;
       	a*=10;
    }
    return s;
}
```

