# 栈

```
// 定义（先进后出）
stack<int> st;  // 基本写法
stack<pair<int, int>> st1;  // 存 pair
struct Node {
	int a;
	int b;
	bool f;
};
stack<Node> st2;  // 存结构体

// 入栈
st.push(1);
st1.push({2, 3});
st2.push({4, 5, true});

// 访问（只能访问栈顶）
int top = st.top();  // 取栈顶
int top1 = st1.top().first;  // 取 pair 第一项
int top1_2 = st1.top().second;  // 取 pair 第二项
int top2 = st2.top().a;  // 取结构体
```

